import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import express from 'express';
import jwt from 'jsonwebtoken';
import {enforceBackofficeStaff} from '../../src/services/backoffice-staff-access.js';
import {readStaffWorkforceView} from '../../src/services/backoffice-staff-workforce.js';
import {assertCustomerDemoRuntimeClosed} from '../../src/customer-demo-runtime.js';

// Invoked only inside the native isolated BASE/CAPTURE database fixture.
export async function verifyNativeWorkforceReads({db}){
 const caps=['workforce-roles.read','workforce-rules.read','shift-templates.read','workforce-audit.read'];
 await db.$transaction(async tx=>{
  await tx.$queryRawUnsafe("SELECT set_config('mws.lifecycle_generations',$1,true)",JSON.stringify({selected:'7',sibling:'0',foreign:'0'}));
  const insert=async(table,row)=>{const entries=Object.entries(row);await tx.$executeRawUnsafe(`INSERT INTO "${table}"(${entries.map(([k])=>'"'+k+'"').join(',')}) VALUES (${entries.map((_,i)=>'$'+(i+1)).join(',')})`,...entries.map(([,v])=>v))};
  await tx.$executeRawUnsafe('UPDATE "BackofficeStaffGrant" SET "capabilities"=$1::jsonb WHERE "userId"=\'staff\' AND "storeId"=\'selected\'',JSON.stringify(caps));
  await insert('UserSession',{id:'workforce-native-session',userId:'staff',expiresAt:new Date(Date.now()+3600000)});
  for(const moduleKey of ['PERSONNEL_BASIC','PERSONNEL_PRO'])await insert('StorePaidModule',{id:'native-'+moduleKey,companyId:'company',storeId:'selected',moduleKey,active:true,updatedAt:new Date()});
  for(const [id,companyId]of[['visible','company'],['hidden','company'],['unreferenced','company'],['foreign','foreign']])await insert('WorkforceRole',{id:'wf-role-'+id,companyId,name:'Role '+id,code:'NATIVE_'+id,updatedAt:new Date()});
  for(const [id,companyId,baseStoreId]of[['selected','company','selected'],['hidden','company','sibling'],['access','company','sibling'],['foreign','foreign','foreign']])await insert('WorkforceEmployee',{id:'wf-employee-'+id,companyId,baseStoreId,fullName:'Employee '+id,email:'PII_CANARY@invalid.test',phone:'PII_CANARY',pinHash:'PII_CANARY',notes:'PII_CANARY',updatedAt:new Date()});
  await insert('WorkforceEmployeeStoreAccess',{id:'wf-access',employeeId:'wf-employee-access',storeId:'selected',active:true,updatedAt:new Date()});
  for(const [id,employeeId,roleId]of[['one','selected','visible'],['two','access','visible'],['three','hidden','hidden'],['four','foreign','foreign']])await insert('WorkforceEmployeeRole',{id:'wf-er-'+id,employeeId:'wf-employee-'+employeeId,roleId:'wf-role-'+roleId});
  for(const [id,employeeId,relatedEmployeeId,ruleType,value]of[['days','selected','hidden','MIN_DAYS_OFF',{days:2,secret:'PII_CANARY'}],['hours','access','foreign','MAX_HOURS_PER_WEEK',{hours:32,secret:'PII_CANARY'}],['related','selected','access','INCOMPATIBLE_EMPLOYEE',{secret:'PII_CANARY'}],['hidden','hidden',null,'NO_WEEKEND',{}]])await tx.$executeRawUnsafe('INSERT INTO "WorkforceEmployeeRule"("id","employeeId","relatedEmployeeId","ruleType","valueJson","updatedAt") VALUES($1,$2,$3,$4,$5::jsonb,NOW())','wf-rule-'+id,'wf-employee-'+employeeId,relatedEmployeeId?'wf-employee-'+relatedEmployeeId:null,ruleType,JSON.stringify(value));
  for(const [id,companyId,storeId,role]of[['selected','company','selected','visible'],['bad-role','company','selected','foreign'],['sibling','company','sibling','visible'],['foreign','foreign','foreign','foreign']])await insert('WorkforceShiftTemplate',{id:'wf-template-'+id,companyId,storeId,name:'Template '+id,code:'T_'+id,startTime:'07:00',endTime:'15:00',requiredRoleId:'wf-role-'+role,updatedAt:new Date()});
  for(const storeId of ['selected','sibling'])await insert('WorkforceSchedule',{id:'wf-schedule-'+storeId,companyId:'company',storeId,periodStart:new Date('2026-11-16'),periodEnd:new Date('2026-11-22'),updatedAt:new Date()});
  for(const [id,storeId]of[['one','selected'],['two','sibling']])await insert('WorkforceScheduleAssignment',{id:'wf-assignment-'+id,scheduleId:'wf-schedule-'+storeId,date:new Date('2026-11-18'),shiftTemplateId:'wf-template-selected',updatedAt:new Date()});
  for(const [id,companyId,storeId,after]of[['cleared','company','selected',{employeeId:null,shiftTemplateId:null,ruleCode:null}],['outside','company','selected',{employeeId:'wf-employee-hidden',shiftTemplateId:'wf-template-sibling',secret:'PII_CANARY'}],['sibling','company','sibling',{}],['foreign','foreign','foreign',{}]])await tx.$executeRawUnsafe('INSERT INTO "WorkforceAuditLog"("id","companyId","storeId","action","entityType","beforeJson","afterJson","ipAddress","deviceName") VALUES($1,$2,$3,\'WORKFORCE_UPDATED\',\'WORKFORCE_EMPLOYEE\',$4::jsonb,$5::jsonb,\'PII_CANARY\',\'PII_CANARY\')','wf-audit-'+id,companyId,storeId,JSON.stringify({employeeId:'wf-employee-selected',shiftTemplateId:'wf-template-selected',ruleCode:'MIN_DAYS_OFF',secret:'PII_CANARY'}),JSON.stringify(after));
 },{timeout:30000});
 const mutate=(sql,...values)=>db.$transaction(async tx=>{await tx.$queryRawUnsafe("SELECT set_config('mws.lifecycle_generations',$1,true)",JSON.stringify({selected:'7',sibling:'0',foreign:'0'}));return tx.$executeRawUnsafe(sql,...values)});
 const saved=process.env.JWT_SECRET;process.env.JWT_SECRET='isolated-native-workforce-secret';let server;
 try{
  let afterRead=null,reads=0;
  const readDb=new Proxy(db,{get(target,key){if(['$executeRaw','$executeRawUnsafe','$transaction'].includes(key))return()=>assert.fail('native read attempted write/bootstrap/transaction');const value=target[key];if(key==='$queryRaw')return async(...args)=>{const sql=args[0].join('?');assert.doesNotMatch(sql,/\b(?:INSERT|UPDATE|DELETE|CREATE|ALTER|FOR UPDATE)\b/);const rows=await value.apply(target,args);if(/FROM "Workforce(?:Role|EmployeeRule|ShiftTemplate|AuditLog)"/.test(sql)){reads++;if(afterRead){const action=afterRead;afterRead=null;await action()}}return rows};return typeof value==='function'?value.bind(target):value}});
  const source=await readFile(new URL('../../src/middleware/auth.js',import.meta.url),'utf8');
  const auth=new Function('prisma','jwt','assertCustomerDemoRuntimeClosed','enforceBackofficeStaff',source.slice(source.indexOf('export async function auth(')).replace('export async function auth','async function auth')+';return auth;')(readDb,jwt,assertCustomerDemoRuntimeClosed,enforceBackofficeStaff);
  const app=express();app.use(express.json());const index=await readFile(new URL('../../src/index.js',import.meta.url),'utf8'),start=index.indexOf('// Exact delegated workforce settings'),end=index.indexOf('app.use("/api/platform",auth,platformAuditCapture)',start);assert.ok(start>0&&end>start);new Function('app','auth','readStaffWorkforceView','prisma',index.slice(start,end))(app,auth,readStaffWorkforceView,readDb);app.use((_req,res)=>res.status(404).json({code:'UNEXPECTED_NATIVE_FALLTHROUGH'}));app.use((e,_req,res,_next)=>res.status(e.status||500).json({code:e.code}));
  server=app.listen(0,'127.0.0.1');await new Promise(resolve=>server.once('listening',resolve));
  const token=jwt.sign({id:'staff',companyId:'company',role:'EMPLOYEE',tokenType:'BACKOFFICE_USER',staffAccess:true,sessionId:'workforce-native-session',sessionVersion:0},process.env.JWT_SECRET);
  const get=async(view,{company='company',store='selected',header='selected'}={})=>{const r=await fetch(`http://127.0.0.1:${server.address().port}/api/platform/store-modules/companies/${company}/stores/${store}/workforce-v2/${view}`,{headers:{authorization:'Bearer '+token,'x-backoffice-store-id':header}});return {status:r.status,body:await r.json()}};
  await mutate('UPDATE "CompanyModule" SET "active"=false WHERE "companyId"=\'company\' AND "moduleKey"=\'INVENTORY\'');
  const data={};for(const view of ['roles','rules','shift-templates','audit']){const r=await get(view);assert.equal(r.status,200,JSON.stringify(r));assert.equal(r.body.companyId,'company');assert.equal(r.body.storeId,'selected');assert.equal(r.body.readOnly,true);assert.doesNotMatch(JSON.stringify(r.body),/PII_CANARY/);data[view]=r.body.items}
  assert.deepEqual(data.roles.map(r=>r.id),['wf-role-visible']);assert.equal(data.roles[0].employeeCount,2);assert.equal(data.roles[0].shiftTemplateCount,1);
  assert.equal(data.rules.length,3);const rules=Object.fromEntries(data.rules.map(r=>[r.id,r]));assert.deepEqual(rules['wf-rule-days'].value,{days:2});assert.deepEqual(rules['wf-rule-hours'].value,{hours:32});assert.equal(rules['wf-rule-days'].relatedEmployeeId,null);assert.equal(rules['wf-rule-hours'].relatedEmployeeId,null);assert.equal(rules['wf-rule-related'].relatedEmployeeId,'wf-employee-access');
  assert.equal(data['shift-templates'].length,2);const templates=Object.fromEntries(data['shift-templates'].map(r=>[r.id,r]));assert.equal(templates['wf-template-selected'].assignmentCount,1);assert.equal(templates['wf-template-bad-role'].requiredRoleUnavailable,true);assert.equal(templates['wf-template-bad-role'].requiredRoleId,null);assert.equal(templates['wf-template-bad-role'].requiredRole,null);
  assert.equal(data.audit.length,2);for(const row of data.audit){assert.equal(row.employeeName,null);assert.equal(row.shift,null);assert.equal(Object.hasOwn(row,'beforeJson'),false)}assert.equal(data.audit.find(r=>r.id==='wf-audit-cleared').ruleCode,null);
  for(const [view,options]of [['roles',{company:'foreign'}],['roles',{store:'sibling',header:'sibling'}],['roles',{header:'sibling'}],['roles?employeeId=foreign',{}],['bootstrap',{}]]){const before=reads;assert.equal((await get(view,options)).status,403);assert.equal(reads,before)}
  await mutate('UPDATE "StorePaidModule" SET "active"=false WHERE "id"=\'native-PERSONNEL_PRO\'');assert.equal((await get('rules')).status,403);assert.equal((await get('roles')).status,200);await mutate('UPDATE "StorePaidModule" SET "active"=true WHERE "id"=\'native-PERSONNEL_PRO\'');
  for(const table of ['BackofficeStaffAccount','BackofficeStaffGrant']){afterRead=()=>mutate(`UPDATE "${table}" SET "revision"="revision"+1 WHERE "userId"='staff'`);assert.equal((await get('roles')).status,403,'actual data must be withheld after concurrent revision change')}
  afterRead=()=>mutate("UPDATE \"BackofficeStaffGrant\" SET \"capabilities\"='[]'::jsonb WHERE \"userId\"='staff'");assert.equal((await get('audit')).status,403,'revoked capability must withhold already-read audit metadata');
  await mutate('UPDATE \"BackofficeStaffGrant\" SET \"capabilities\"=$1::jsonb WHERE \"userId\"=\'staff\'',JSON.stringify(caps));
  await mutate('UPDATE "StorePaidModule" SET "active"=false WHERE "id" IN (\'native-PERSONNEL_BASIC\',\'native-PERSONNEL_PRO\')');for(const view of ['roles','shift-templates','audit'])assert.equal((await get(view)).status,403);
 }finally{if(server){server.closeAllConnections();await new Promise(resolve=>server.close(resolve))}if(saved===undefined)delete process.env.JWT_SECRET;else process.env.JWT_SECRET=saved}
}
